INSERT IGNORE INTO `departments` (`department_id`, `name`, `code`, `description`, `parent_department_id`, `manager_employee_id`, `level`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'مكتب الوزير', 'EXECUTIVE', 'مسؤولة عن اتخاذ القرارات الوزارية، اعتماد السياسات والخطط الاستراتيجية، الإشراف العام على أعمال الوزارة، والتنسيق على مستوى القيادات العليا. لا تتولى تنفيذ المهام التشغيلية أو التقنية أو المالية بشكل مباشر.', NULL, 1, 1, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(2, 'ديوان الوزارة', 'SECRETARIAT', 'مسؤولة عن إدارة أعمال ديوان الوزارة، المراسلات الرسمية، إدارة الوثائق والأرشفة، تنظيم الاجتماعات، ومتابعة المعاملات الإدارية.', 1, 2, 2, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(4, 'الإدارة العامة للشؤون المالية', 'FINANCE', 'مسؤولة عن الإدارة المالية، إعداد التقارير المالية، المحاسبة، الرقابة على الإنفاق، إدارة الموارد المالية، وضمان الالتزام باللوائح المالية.', 2, 4, 3, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(5, 'الإدارة العامة للشؤون الإدارية', 'ADMIN', 'مسؤولة عن الخدمات الإدارية، الشؤون الإدارية، إدارة المرافق، تنظيم الأعمال المكتبية، وتقديم الدعم الإداري للإدارات المختلفة.', 2, 5, 3, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(6, 'الإدارة العامة لتقنية المعلومات', 'IT', 'مسؤولة عن التحول الرقمي، تطوير الأنظمة، إدارة قواعد البيانات، تطوير البرمجيات، إدارة البنية التحتية التقنية، الشبكات، الخوادم، الأمن السيبراني، الذكاء الاصطناعي، والدعم الفني.', 2, 6, 3, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(7, 'الإدارة العامة للتخطيط', 'PLANNING', 'مسؤولة عن إعداد الخطط الاستراتيجية والتشغيلية، متابعة تنفيذ المبادرات، إدارة الأداء المؤسسي، متابعة مؤشرات الأداء، وتحليل نتائج التنفيذ.', 2, 7, 3, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(8, 'الإدارة العامة للشؤون القانونية', 'LEGAL', 'مسؤولة عن تقديم الاستشارات القانونية، مراجعة العقود، إعداد اللوائح والتنظيمات، ضمان الالتزام بالأنظمة، وتمثيل الوزارة في الجوانب القانونية.', 2, 8, 3, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(10, 'إدارة المشتريات والمخازن', 'PROCUREMENT', 'مسؤولة عن المشتريات الحكومية، إدارة المناقصات، التعاقد مع الموردين، إدارة المخازن، استلام وصرف المواد، وضمان توفر الاحتياجات التشغيلية.', 4, 10, 4, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(11, 'إدارة الميزانية', 'BUDGET', 'مسؤولة عن إعداد الموازنة، توزيع الاعتمادات المالية، متابعة تنفيذ الموازنة، تحليل الانحرافات، وإعداد التقديرات المالية المستقبلية.', 4, 11, 4, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:14'),
(13, 'إدارة التدريب', 'TRAINING', 'مسؤولة عن إعداد وتنفيذ البرامج التدريبية، تطوير مهارات الموظفين، بناء القدرات، إعداد الخطط التدريبية، ورفع الكفاءة المؤسسية.', 5, 13, 4, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:15'),
(14, 'إدارة الأنظمة', 'SYSTEMS', 'مسؤولة عن تحليل وتصميم وتطوير الأنظمة الإلكترونية، صيانة التطبيقات، التكامل بين الأنظمة، إدارة الخدمات الإلكترونية، ودعم الأنظمة المؤسسية.', 6, 14, 4, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:15'),
(15, 'إدارة الشبكات', 'NETWORK', 'مسؤولة عن إدارة الشبكات، الخوادم، البنية التحتية التقنية، مراكز البيانات، الاتصالات، ضمان استمرارية الخدمات التقنية، ومعالجة الأعطال.', 6, 15, 4, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:15'),
(16, 'إدارة الأمن السيبراني', 'CYBERSECURITY', 'مسؤولة عن حماية الأنظمة والمعلومات، إدارة الأمن السيبراني، مراقبة التهديدات الأمنية، الاستجابة للحوادث، إدارة الهوية والصلاحيات، وضمان الامتثال لمعايير أمن المعلومات.', 6, 16, 4, 1, '2024-12-31 21:00:00', '2026-07-27 23:09:15');
