INSERT IGNORE INTO `pestel_analysis` (`id`, `department_id`, `political`, `economic`, `social`, `technological`, `environmental`, `legal`, `analysis_date`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 7, 'عدم الاستقرار السياسي وتأثيره على تنفيذ الخطط طويلة الأجل.\r\nتعدد مراكز القرار وتأثيره على التنسيق المؤسسي.\r\nالسياسات الحكومية المتعلقة بإدارة الموارد الطبيعية.', 'تقلب أسعار النفط والمعادن عالميًا.\r\nمحدودية الموارد المالية المتاحة لتمويل المشاريع.\r\nارتفاع تكاليف التشغيل والصيانة.\r\nتذبذب الاستثمارات المحلية والأجنبية.\r\nأهمية القطاع النفطي والمعدني في دعم الإيرادات الوطنية.', 'الحاجة إلى توفير فرص عمل وتنمية الكفاءات الوطنية.\r\nتوقعات المجتمع بشأن الشفافية وإدارة الموارد العامة.\r\nأهمية إشراك المجتمعات المحلية في المشاريع ذات التأثير المباشر عليها.\r\nالحاجة إلى تطوير مهارات العاملين في القطاع.', 'التطور السريع في تقنيات الاستكشاف والإنتاج.\r\nإمكانية استخدام الذكاء الاصطناعي في تحليل البيانات والتنبؤ بالمخاطر.\r\nالحاجة إلى تحديث البنية التحتية الرقمية.\r\nتوفر تقنيات نظم المعلومات الجغرافية والاستشعار عن بعد.\r\nمخاطر الهجمات السيبرانية والتحديات المتعلقة بأمن المعلومات.\r\nإمكانية أتمتة الإجراءات الإدارية والرقابية.', 'مخاطر التلوث النفطي والتسربات.\r\nالتأثيرات البيئية لعمليات التعدين والاستخراج.\r\nندرة المياه وتأثيرها على الأنشطة الصناعية.\r\nالحاجة إلى تطبيق معايير السلامة البيئية.\r\nتغير المناخ وتأثيره على البنية التحتية والعمليات.\r\nالحاجة إلى خطط الاستجابة للطوارئ البيئية.', 'التشريعات المنظمة لقطاع النفط والمعادن.\r\nالقوانين المتعلقة بالاستثمار والتراخيص والامتيازات.\r\nمتطلبات الالتزام بالمعايير البيئية والسلامة المهنية.', '2025-01-10', 7, '2025-01-10 06:00:00', '2026-10-29 21:45:18');
